import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// tailwind-merge must know the MWDS type-scale utilities generated by the
// Tailwind bridge (text-p-sm, text-h2, …). Otherwise it would treat them as
// text *colors* and drop e.g. `text-primary-foreground` when both are present.
const twMerge = extendTailwindMerge({
  extend: {
    theme: {
      text: ["p-mini", "p-sm", "p", "p-lg", "caption", "h1", "h2", "h3", "h4"],
    },
  },
});

/** shadcn/ui-compatible class combiner. */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
